    'nav.fans-report':       { en: 'Fan analytics', zh: '粉絲分析' },
    'nav.fans-audience':     { en: 'Fan analytics · incl. external', zh: '粉絲分析：含外部' },
    'nav.fans-vault-sub':    { en: 'Gated vaults of media',           zh: '有門檻的媒體庫房' },
    'fg.crumb.fans':  { en: 'Fans', zh: '粉絲' },
