    'fg.title':       { en: 'Stop guessing <em>who</em> your real fans are.', zh: '不用再猜<em>誰</em>是你的鐵粉。' },
    'fg.sub':         { en: 'Ztor turns \u201Csomeone is watching\u201D into \u201CI know who, what they did, and what I can give them.\u201D Here are the four things it does for you.', zh: 'Ztor 幫你把「有人在看」變成「我知道是誰、他做了什麼、我能給他什麼」。以下是這套系統為你做的四件事。' },
