    'fg.a1.b':        { en: 'Follower counts tell you how many. Loyalty points tell you <strong>who actually showed up</strong> \u2014 what they bought, watched, attended. Every fan has a rank, and the order is data, not your impression.', zh: '追蹤數只告訴你有多少人。忠誠點數告訴你<strong>誰真的來了</strong>——買過什麼、看過什麼、來過幾場。每位粉絲都有名次，排序不是你的印象，是資料。' },
    'fg.a2.t':        { en: 'Then decide what each tier unlocks', zh: '再決定每個分級拿得到什麼' },
    'fg.a2.b':        { en: 'Define a perk <strong>once</strong> and all four tiers get a slot for it \u2014 you just choose who it opens for. Want something of your own? Type a name and it becomes a row.', zh: '權益只需要<strong>定義一次</strong>，四個分級自動都有欄位，你只要決定開給誰。想加一項自己的專屬內容？打上名字就多一列。' },
    'fg.a3.t':        { en: 'Make climbing worth it', zh: '讓往上爬這件事本身變好玩' },
    'fg.a3.b':        { en: 'The higher the tier, the rarer the reward \u2014 a set visit, a live recording session, exclusive auctions, your whole VIP media vault. Fans can see <strong>what the next rung unlocks</strong>, so they have a reason to take one more step.', zh: '越上面的分級，能拿到的東西越稀有——片場探班、參觀現場錄音、專屬拍賣、整座 VIP 影音庫。粉絲看得到<strong>下一階解鎖什麼</strong>，所以他們有理由再往上一步。' },
    'fg.a4.t':        { en: 'And earn from what they buy anyway', zh: '最後，讓粉絲的日常消費也回你身上' },
    'fg.a4.b':        { en: 'A fan buys a coffee at Starbucks, gets a reward code, scans it for points \u2014 and you take a cut. <strong>You never sign with the brand</strong>; Ztor already did. You pick the brand, set your window, and tell your fans to scan.', zh: '粉絲在星巴克買一杯咖啡，拿到回饋碼、掃碼集點——而你抽一份分潤。<strong>你不必跟品牌簽約</strong>，Ztor 已經談好了；你只要挑品牌、訂檔期，然後告訴粉絲去掃碼。' },
