    'rep.points.meta': { en: 'Points this campaign put into your fans’ accounts. Points feed tier standing, so a campaign also moves fans up the ladder.', zh: '本次合作為粉絲帳戶帶來的點數。點數會計入分級，所以合作同時也推動粉絲往上爬。' },
