    'rep.open.text': { en: 'Ztor sees scans, not tills. How many codes the brand handed out, and what each fan actually spent, live in the brand’s systems — so neither is shown rather than estimated.', zh: 'Ztor 看得到掃碼，看不到收銀機。品牌實際發出多少張回饋碼、每位粉絲實際消費多少，都在品牌自己的系統裡——所以寧可不顯示，也不用估算充數。' },
    'rep.demo-note': { en: 'Prototype figures for illustration. Platform fee on campaign revenue is not yet applied — the figure shown is gross.', zh: '原型示意數據。合作分潤的平台費尚未套用，此處顯示的是未扣除前的金額。' },
    'rep.chosen.exp.title': { en: 'Chosen vs defaulted', zh: '主動選擇 vs 接受預設' },
    'rep.chosen.exp.lead': { en: 'When a fan scans a reward code, the app pre-selects a creator for them — usually whoever they engage with most. They can change it.', zh: '粉絲掃描回饋碼時，App 會先預選一位創作者——通常是他互動最多的那位。粉絲可以改選。' },
    'rep.chosen.exp.body': { en: 'So two very different things both arrive as “a scan”. One fan tapped past their default to name you. Another simply accepted the name already on screen. Only the first is evidence that your campaign persuaded anybody.', zh: '所以兩件很不一樣的事，都會以「一次掃碼」的形式出現。一位粉絲越過預設、指定了你；另一位只是接受了畫面上原本的名字。只有前者能證明你的推廣真的說服了誰。' },
    'rep.chosen.exp.eg': { en: 'Two campaigns both credit <strong>500 scans</strong>. In one, <strong>90%</strong> actively picked you — your promotion worked. In the other, <strong>15%</strong> did — you were collecting scans you would have received anyway.', zh: '兩次合作同樣歸屬 <strong>500 次掃碼</strong>。其中一次有 <strong>90%</strong> 是主動選你——推廣奏效。另一次只有 <strong>15%</strong>——你收到的是本來就會來的掃碼。' },
    'rep.chosen.exp.rule': { en: 'A high total with a low choice rate means the campaign is riding your existing audience, not growing it.', zh: '總數高但主動選擇率低，代表這次合作是在吃既有受眾的紅利，而不是把受眾做大。' },
