    /* 說明改成資訊鈕＋彈窗（同一段話重複六次是雜訊）。每張分級卡的鈕都指向同一份說明。 */
    'tier-settings.gate.toppct-explain': { en: 'How “Top %” works', zh: '「前 % 名」怎麼算' },
    'tier-settings.gate.points-explain': { en: 'Why there is also a points floor', zh: '為什麼還要有點數下限' },
    'tier-settings.explain.close': { en: 'Close', zh: '關閉' },
    'tier-settings.explain.example': { en: 'Example', zh: '範例' },
    'tier-settings.explain.toppct.title': { en: 'How “Top %” works', zh: '「前 % 名」怎麼算' },
    'tier-settings.explain.toppct.lead': { en: 'A <strong>relative</strong> gate. It asks where a fan sits compared with everyone else — not how much they have.', zh: '這是<strong>相對</strong>門檻：看的是這位粉絲在所有人之中排在哪裡，不是他累積了多少。' },
    'tier-settings.explain.toppct.s1': { en: 'Every fan is ranked by loyalty points, highest first.', zh: '所有粉絲依忠誠點數由高到低排名。' },
    'tier-settings.explain.toppct.s2': { en: 'Their rank becomes a percentile — rank ÷ total fans.', zh: '名次換算成百分位——名次 ÷ 粉絲總數。' },
    'tier-settings.explain.toppct.s3': { en: '“Top 10%” means the highest-scoring tenth of your audience.', zh: '「前 10%」就是點數最高的那十分之一。' },
    'tier-settings.explain.toppct.eg': { en: 'With <strong>1,840 fans</strong>, Top 10% is the highest-ranked <strong>184</strong> of them.', zh: '有 <strong>1,840 位</strong>粉絲時，前 10% 就是排名最前的 <strong>184 位</strong>。' },
    'tier-settings.explain.toppct.note': { en: 'Because it is relative, the bar moves as your audience grows. A fan can drop out of the top 10% without losing a single point — someone else simply overtook them.', zh: '因為是相對的，粉絲變多時這條線會跟著移動。一位粉絲可能一點都沒少，卻掉出前 10%——只是被別人超車了。' },
    'tier-settings.explain.points.title': { en: 'Why there is also a points floor', zh: '為什麼還要有點數下限' },
    'tier-settings.explain.points.lead': { en: 'An <strong>absolute</strong> gate. A percentile always produces a top 1% — even in a tiny audience. The floor is what stops a tier being handed out to someone who has not earned it.', zh: '這是<strong>絕對</strong>門檻。百分位一定算得出「前 1%」——就算總共只有幾十個人也一樣。點數下限就是用來擋住「還沒真的達標卻被發了分級」。' },
    'tier-settings.explain.points.eg': { en: 'A creator with <strong>40 fans</strong>: the top 1% is one person. If that fan has <strong>120 points</strong> and Inner Circle’s floor is <strong>800</strong>, they still do not enter. The tier stays empty until someone genuinely reaches it.', zh: '一位創作者只有 <strong>40 位</strong>粉絲：前 1% 就是一個人。若這位粉絲只有 <strong>120 點</strong>，而核心圈的下限是 <strong>800</strong>，他仍然進不去。這個分級會一直空著，直到有人真的達標。' },
    'tier-settings.explain.points.rule': { en: 'A fan must clear both gates. Being top 1% is not enough on its own, and neither is a high score outside the percentile.', zh: '兩道門檻都要通過。只在前 1% 不夠，點數再高但排不進百分位也不夠。' },
