    'ar.unit.people':     { en: 'people',  zh: '人' },

    /* 頁首 KPI：總數旁邊就放它的組成。三種「次」不是同一種次——一次觀看是
       一部電影、一次串流是一首歌——所以總和只看得出規模，不是表現指標。 */
    'ar.kpi.total':       { en: 'Total plays', zh: '總瀏覽量' },
    'ar.kpi.total-meta':  { en: 'A summed count — a play isn’t the same size across the three', zh: '三者「一次」的份量不同，這裡呈現的是加總後的次數' },
    'ar.kpi.film':        { en: 'Film & TV views', zh: '影視總觀看次數' },
    'ar.kpi.music':       { en: 'Music streams',   zh: '音樂總串流次數' },
    'ar.kpi.post':        { en: 'Post views',      zh: '貼文總瀏覽量' },
    'ar.kpi.share':       { en: '{p} of the total', zh: '佔總量 {p}' },

    'ar.top':             { en: 'Top 10 by views', zh: 'Top 10 瀏覽次數' },
